// Command genp6derived regenerates the derived entries of the P6 conformance corpus
// from their stated inputs: the key identifier, subject, signed message and
// deterministic signature entries, and the composite message representative.
//
// Usage:
//
//	genp6derived [-vectors dir] [-check]
//
// Without -check the command rewrites every entry file that differs from its
// regenerated bytes. With -check it writes nothing and exits 1 when any file
// differs or is missing. The default vectors directory is vectors/v2/P6 of the
// repository that contains the working directory.
package main

import (
	"bytes"
	"crypto/ed25519"
	"crypto/mldsa"
	"crypto/sha256"
	"crypto/sha512"
	"encoding/hex"
	"encoding/json"
	"errors"
	"flag"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"sort"

	v2 "go.blackcatinformatics.ca/gts/v2"
)

// compositeLabel is the context of the ML-DSA-65 half of the composite signature (P6 4.2).
const compositeLabel = "COMPSIG-MLDSA65-Ed25519-SHA512"

// compositePrefix opens the message representative M' (P6 4.2).
const compositePrefix = "CompositeAlgorithmSignatures2025"

// The fixed inputs of the derived entries.
var (
	ed25519Seed   = sequence(0x00, 32)
	compositeSeed = sequence(0x40, 64)
	headerID      = digestOf(sequence(0x00, 32))
	frameID       = digestOf(sequence(0x20, 32))
	subjectKey    = digestOf(sequence(0x01, 32))
	subjectH0     = digestOf(sequence(0x21, 32))
	subjectFrame  = digestOf(sequence(0x41, 32))
	representedIn = sequence(0x00, 32)
)

func main() {
	if err := run(os.Args[1:], os.Stderr); err != nil {
		fmt.Fprintln(os.Stderr, "genp6derived:", err)
		os.Exit(1)
	}
}

// errDiffers reports that -check found entries that differ from their regenerated bytes.
var errDiffers = errors.New("derived entries differ")

func run(args []string, log io.Writer) error {
	flags := flag.NewFlagSet("genp6derived", flag.ContinueOnError)
	flags.SetOutput(log)
	dir := flags.String("vectors", "", "the P6 vectors directory (default: vectors/v2/P6 of the enclosing repository)")
	check := flags.Bool("check", false, "write nothing; exit 1 if any entry differs")
	if err := flags.Parse(args); err != nil {
		return err
	}
	if *dir == "" {
		found, err := defaultDir()
		if err != nil {
			return err
		}
		*dir = found
	}
	files, err := build()
	if err != nil {
		return err
	}
	differing, err := compare(*dir, files)
	if err != nil {
		return err
	}
	for _, name := range differing {
		if _, err := fmt.Fprintln(log, "differs:", name); err != nil {
			return err
		}
	}
	if *check {
		if len(differing) > 0 {
			return fmt.Errorf("%w: %d of %d files", errDiffers, len(differing), len(files))
		}
		return nil
	}
	for _, name := range differing {
		//nolint:gosec // the corpus files are repository files, which are world-readable.
		if err := os.WriteFile(filepath.Join(*dir, name), files[name], 0o644); err != nil {
			return err
		}
	}
	return nil
}

// defaultDir finds vectors/v2/P6 in the working directory or the nearest ancestor that has it.
func defaultDir() (string, error) {
	dir, err := os.Getwd()
	if err != nil {
		return "", err
	}
	for {
		candidate := filepath.Join(dir, "vectors", "v2", "P6")
		if info, err := os.Stat(candidate); err == nil && info.IsDir() {
			return candidate, nil
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			return "", errors.New("no vectors/v2/P6 directory above the working directory; pass -vectors")
		}
		dir = parent
	}
}

// compare returns, in order, the names of files whose bytes on disk differ from files.
// A missing file differs; any other read error is returned.
func compare(dir string, files map[string][]byte) ([]string, error) {
	names := make([]string, 0, len(files))
	for name := range files {
		names = append(names, name)
	}
	sort.Strings(names)
	var differing []string
	for _, name := range names {
		//nolint:gosec // dir is the corpus directory the program was given, and name is a fixed corpus file name.
		//nolint:gosec // dir is the corpus directory the program was given, and name is a fixed corpus file name.
		onDisk, err := os.ReadFile(filepath.Join(dir, name))
		if errors.Is(err, os.ErrNotExist) {
			differing = append(differing, name)
			continue
		}
		if err != nil {
			return nil, err
		}
		if !bytes.Equal(onDisk, files[name]) {
			differing = append(differing, name)
		}
	}
	return differing, nil
}

func sequence(start byte, length int) []byte {
	out := make([]byte, length)
	for i := range out {
		out[i] = start + byte(i)
	}
	return out
}

func digestOf(b []byte) v2.Digest {
	var d v2.Digest
	copy(d[:], b)
	return d
}

// representative returns M' of the composite construction: the prefix, the label, a
// zero-length context and the SHA-512 digest of the message (P6 4.2).
func representative(message []byte) []byte {
	digest := sha512.Sum512(message)
	out := append([]byte(compositePrefix), compositeLabel...)
	out = append(out, 0)
	return append(out, digest[:]...)
}

// compositeKey is a composite signer: its ML-DSA-65 and Ed25519 halves and the public
// key that concatenates their encodings.
type compositeKey struct {
	ml        *mldsa.PrivateKey
	ed        ed25519.PrivateKey
	publicKey []byte
}

func newCompositeKey(private []byte) (compositeKey, error) {
	ml, err := mldsa.NewPrivateKey(mldsa.MLDSA65(), private[:32])
	if err != nil {
		return compositeKey{}, err
	}
	ed := ed25519.NewKeyFromSeed(private[32:])
	public := append(bytes.Clone(ml.PublicKey().Bytes()), ed.Public().(ed25519.PublicKey)...)
	return compositeKey{ml: ml, ed: ed, publicKey: public}, nil
}

// build returns every derived file of the P6 corpus by name.
func build() (map[string][]byte, error) {
	files := map[string][]byte{}
	put := func(name string, doc any) error {
		text, err := marshal(doc)
		if err != nil {
			return fmt.Errorf("%s: %w", name, err)
		}
		files[name] = text
		return nil
	}

	edKey := ed25519.NewKeyFromSeed(ed25519Seed)
	edPublic := edKey.Public().(ed25519.PublicKey)
	edID := v2.KeyIdentifier(v2.Ed25519Algorithm, edPublic)
	edRecord := v2.SignatureRecord{Algorithm: v2.Ed25519Algorithm, KeyID: edID}
	edSubject := v2.SubjectPreimage(edRecord, headerID, frameID)
	edMessage := v2.SignedMessage(edRecord, headerID, frameID)
	edValue := ed25519.Sign(edKey, edMessage[:])

	cp, err := newCompositeKey(compositeSeed)
	if err != nil {
		return nil, err
	}
	cpID := v2.KeyIdentifier(v2.CompositeAlgorithm, cp.publicKey)
	cpRecord := v2.SignatureRecord{Algorithm: v2.CompositeAlgorithm, KeyID: cpID}
	cpSubject := v2.SubjectPreimage(cpRecord, headerID, frameID)
	cpMessage := v2.SignedMessage(cpRecord, headerID, frameID)
	cpRepresentative := representative(cpMessage[:])
	mlHalf, err := cp.ml.SignDeterministic(cpRepresentative, &mldsa.Options{Context: compositeLabel})
	if err != nil {
		return nil, err
	}
	cpValue := append(bytes.Clone(mlHalf), ed25519.Sign(cp.ed, cpRepresentative)...)
	valueSum := sha256.Sum256(cpValue)

	// Each derived signature must verify under the production verifier.
	for _, check := range []struct {
		record v2.SignatureRecord
		value  []byte
		key    []byte
	}{{edRecord, edValue, edPublic}, {cpRecord, cpValue, cp.publicKey}} {
		record := check.record
		record.Value = check.value
		held := v2.HeldKey{KeyID: record.KeyID, Algorithm: record.Algorithm, PublicKey: check.key}
		if r := v2.VerifySignature(record, headerID, frameID, []v2.HeldKey{held}); r.Status != v2.SignatureValid {
			return nil, fmt.Errorf("derived signature of algorithm %d does not verify: %s", record.Algorithm, r.Reason)
		}
	}

	subjects := func(algorithm uint64) (preimage []byte, message v2.Digest) {
		record := v2.SignatureRecord{Algorithm: algorithm, KeyID: subjectKey}
		return v2.SubjectPreimage(record, subjectH0, subjectFrame), v2.SignedMessage(record, subjectH0, subjectFrame)
	}

	docs := []struct {
		name string
		doc  any
	}{
		{"sign-ed25519-reproduce.json", signDoc{
			Name: "sign-ed25519-reproduce", Section: "P6 5", Status: status,
			Note: "the deterministic Ed25519 signature of RFC 8032 for the seed 00 to 1f, whose public key is that of key-id-ed25519, over the subject of the stated header and frame identifiers",
			Cases: []signCase{{
				Signer:        signer{Seed: h(ed25519Seed), PublicKey: h(edPublic), Algorithm: 1, KeyID: h(edID[:])},
				SubjectFields: subjectFields{HeaderIdentifier: h(headerID[:]), FrameIdentifier: h(frameID[:])},
				Result:        signResult{Subject: h(edSubject), Message: h(edMessage[:]), Value: h(edValue)},
			}},
		}},
		{"sign-composite-reproduce.json", compositeSignDoc{
			Name: "sign-composite-reproduce", Section: "P6 5", Status: status,
			Note: "the deterministic composite signature for the stated private key and subject: the value file is the 3373 bytes, the ML-DSA-65 signature of M' with the context Label and rnd of 32 zero bytes, then the Ed25519 signature of M'; it verifies under the public key file",
			Cases: []compositeSignCase{{
				PublicKeyFile: "sign-composite-reproduce.public-key.bin",
				ValueFile:     "sign-composite-reproduce.value.bin",
				Signer:        compositeSigner{PrivateKey: h(compositeSeed), Algorithm: 2, KeyID: h(cpID[:])},
				SubjectFields: subjectFields{HeaderIdentifier: h(headerID[:]), FrameIdentifier: h(frameID[:])},
				Result: compositeSignResult{
					Subject: h(cpSubject), Message: h(cpMessage[:]), MPrime: h(cpRepresentative),
					ValueLength: len(cpValue), ValueSHA256: h(valueSum[:]),
				},
			}},
		}},
		{"key-id-ed25519.json", keyIDDoc[edKeyIDResult]{
			Name: "key-id-ed25519", Status: status, Note: "E([1, PK]) is 36 bytes",
			Cases: []keyIDCase[edKeyIDResult]{{
				InputFile: "key-id-ed25519.bin", Capacity: &wholeCapacity,
				Result: edKeyIDResult{PublicKey: h(edPublic), PreimageLength: 4 + len(edPublic), KeyID: h(edID[:])},
			}},
		}},
		{"key-id-composite.json", keyIDDoc[cpKeyIDResult]{
			Name: "key-id-composite", Section: "P6 3.2", Status: status,
			Note: "the key identifier of a composite key: the input file is the 1984-byte public key (the ML-DSA-65 key of the seed 40 to 5f, then the Ed25519 key of the seed 60 to 7f), E([2, PK2]) is 1989 bytes and begins 82 02 59 07 c0",
			Cases: []keyIDCase[cpKeyIDResult]{{
				InputFile: "key-id-composite.bin",
				Key:       &compositeKeyFields{Algorithm: 2, MLDSASeed: h(compositeSeed[:32]), Ed25519Seed: h(compositeSeed[32:])},
				Result: cpKeyIDResult{
					PreimageHead: "82025907c0", PreimageLength: 5 + len(cp.publicKey), KeyID: h(cpID[:]),
				},
			}},
		}},
	}
	for _, d := range docs {
		if err := put(d.name, d.doc); err != nil {
			return nil, err
		}
	}

	for _, s := range []struct {
		name, note string
		algorithm  uint64
	}{
		{"subject-ed25519", "the typed subject [1, K, H0, F]: the 104 bytes and the 32-byte message", 1},
		{"subject-composite", "the same record with the code 2", 2},
	} {
		preimage, message := subjects(s.algorithm)
		doc := subjectDoc{Name: s.name, Status: status, Note: s.note, Cases: []subjectCase{{
			InputFile: s.name + ".bin", Capacity: wholeCapacity,
			Result: subjectResult{
				Subject: h(preimage), Message: h(message[:]),
				K: h(subjectKey[:]), H0: h(subjectH0[:]), F: h(subjectFrame[:]),
			},
		}}}
		if err := put(s.name+".json", doc); err != nil {
			return nil, err
		}
	}

	if err := put("composite-message-representative.json", representativeDoc{
		Name: "composite-message-representative", Status: status,
		Note: "the 127 bytes of M' for the message 00..1f",
		Cases: []representativeCase{{
			InputFile: "composite-message-representative.bin", Capacity: wholeCapacity,
			Result: representativeResult{Message: h(representedIn), MPrime: h(representative(representedIn))},
		}},
	}); err != nil {
		return nil, err
	}

	files["sign-composite-reproduce.public-key.bin"] = cp.publicKey
	files["sign-composite-reproduce.value.bin"] = cpValue
	files["key-id-composite.bin"] = cp.publicKey
	// These input files carry no bytes: their inputs are stated in the entry.
	for _, name := range []string{
		"key-id-ed25519.bin", "subject-ed25519.bin", "subject-composite.bin", "composite-message-representative.bin",
	} {
		files[name] = []byte{}
	}
	return files, nil
}

const status = "built and matches"

func h(b []byte) string { return hex.EncodeToString(b) }

// marshal renders a document as the corpus lays it out: one-space indentation, declared
// key order and a final newline.
func marshal(doc any) ([]byte, error) {
	text, err := json.MarshalIndent(doc, "", " ")
	if err != nil {
		return nil, err
	}
	return append(text, '\n'), nil
}

type capacity struct {
	StoredBytesPerFrame  uint64 `json:"stored_bytes_per_frame"`
	DecodedBytesPerFrame uint64 `json:"decoded_bytes_per_frame"`
	LabellingUnits       uint64 `json:"labelling_units"`
	LabelledLines        uint64 `json:"labelled_lines"`
	DecodedBytesPerRead  uint64 `json:"decoded_bytes_per_read"`
	ItemsPerRead         uint64 `json:"items_per_read"`
	RebuiltBytesPerRead  uint64 `json:"rebuilt_bytes_per_read"`
	FormedBytesPerRead   uint64 `json:"formed_bytes_per_read"`
	LabelledBytesPerRead uint64 `json:"labelled_bytes_per_read"`
	Access               string `json:"access"`
}

var wholeCapacity = capacity{
	StoredBytesPerFrame: 67108864, DecodedBytesPerFrame: 67108864, LabelledLines: 67108864,
	DecodedBytesPerRead: 68719476736, ItemsPerRead: 67108864,
	RebuiltBytesPerRead: 137438953472, FormedBytesPerRead: 137438953472, LabelledBytesPerRead: 137438953472,
	Access: "whole",
}

type subjectFields struct {
	HeaderIdentifier string `json:"header_identifier"`
	FrameIdentifier  string `json:"frame_identifier"`
}

type signDoc struct {
	Name    string     `json:"name"`
	Section string     `json:"section"`
	Status  string     `json:"status"`
	Note    string     `json:"note"`
	Cases   []signCase `json:"cases"`
}

type signCase struct {
	Label         string        `json:"label"`
	Signer        signer        `json:"signer"`
	SubjectFields subjectFields `json:"subject_fields"`
	Result        signResult    `json:"result"`
}

type signer struct {
	Seed      string `json:"seed"`
	PublicKey string `json:"public_key"`
	Algorithm uint64 `json:"algorithm"`
	KeyID     string `json:"key_id"`
}

type signResult struct {
	Subject string `json:"subject"`
	Message string `json:"message"`
	Value   string `json:"value"`
}

type compositeSignDoc struct {
	Name    string              `json:"name"`
	Section string              `json:"section"`
	Status  string              `json:"status"`
	Note    string              `json:"note"`
	Cases   []compositeSignCase `json:"cases"`
}

type compositeSignCase struct {
	Label         string              `json:"label"`
	PublicKeyFile string              `json:"public_key_file"`
	ValueFile     string              `json:"value_file"`
	Signer        compositeSigner     `json:"signer"`
	SubjectFields subjectFields       `json:"subject_fields"`
	Result        compositeSignResult `json:"result"`
}

type compositeSigner struct {
	PrivateKey string `json:"private_key"`
	Algorithm  uint64 `json:"algorithm"`
	KeyID      string `json:"key_id"`
}

type compositeSignResult struct {
	Subject     string `json:"subject"`
	Message     string `json:"message"`
	MPrime      string `json:"m_prime"`
	ValueLength int    `json:"value_length"`
	ValueSHA256 string `json:"value_sha256"`
}

type keyIDDoc[R any] struct {
	Name    string         `json:"name"`
	Section string         `json:"section,omitempty"`
	Status  string         `json:"status"`
	Note    string         `json:"note"`
	Cases   []keyIDCase[R] `json:"cases"`
}

type keyIDCase[R any] struct {
	Label     string              `json:"label"`
	InputFile string              `json:"input_file"`
	Capacity  *capacity           `json:"capacity,omitempty"`
	Key       *compositeKeyFields `json:"key,omitempty"`
	Result    R                   `json:"result"`
}

type compositeKeyFields struct {
	Algorithm   uint64 `json:"algorithm"`
	MLDSASeed   string `json:"mldsa_seed"`
	Ed25519Seed string `json:"ed25519_seed"`
}

type edKeyIDResult struct {
	PublicKey      string `json:"public_key"`
	PreimageLength int    `json:"preimage_length"`
	KeyID          string `json:"key_id"`
}

type cpKeyIDResult struct {
	PreimageHead   string `json:"preimage_head"`
	PreimageLength int    `json:"preimage_length"`
	KeyID          string `json:"key_id"`
}

type subjectDoc struct {
	Name   string        `json:"name"`
	Status string        `json:"status"`
	Note   string        `json:"note"`
	Cases  []subjectCase `json:"cases"`
}

type subjectCase struct {
	Label     string        `json:"label"`
	InputFile string        `json:"input_file"`
	Capacity  capacity      `json:"capacity"`
	Result    subjectResult `json:"result"`
}

type subjectResult struct {
	Subject string `json:"subject"`
	Message string `json:"message"`
	K       string `json:"K"`
	H0      string `json:"H0"`
	F       string `json:"F"`
}

type representativeDoc struct {
	Name   string               `json:"name"`
	Status string               `json:"status"`
	Note   string               `json:"note"`
	Cases  []representativeCase `json:"cases"`
}

type representativeCase struct {
	Label     string               `json:"label"`
	InputFile string               `json:"input_file"`
	Capacity  capacity             `json:"capacity"`
	Result    representativeResult `json:"result"`
}

type representativeResult struct {
	Message string `json:"message"`
	MPrime  string `json:"m_prime"`
}
